"""Model linter (FR-120). Catalog: docs/LINT-RULES.md (generated by ``catalog_markdown``).

Rules are pure functions over an identified ``AppModel``. Error-severity findings block a
revision unless suppressed by a ``lint_suppressions`` entry, which carries a justification and
is stored with the revision so the decision is auditable.
"""

from __future__ import annotations

import re
from collections.abc import Callable, Iterator
from dataclasses import dataclass
from typing import Literal

from orchivio.expr import (
    CheckEnv,
    ExprError,
    NotCompilable,
    SqlContext,
    UserRef,
    check,
    compile_predicate,
)
from orchivio.expr.ast import BOOL

from .ids import iter_elements
from .refs import build_refs
from .schema import AppModel, EntityDef, ModuleDef, parse_field_type
from .validate import ModelIndex

Severity = Literal["error", "warning", "info"]
Category = Literal["security", "performance", "maintainability", "accessibility"]

_SENSITIVE = re.compile(r"(password|passwd|secret|token|api_?key|ssn|credit_?card)", re.I)
WRITE_OPS = {"create", "update", "delete"}


@dataclass(frozen=True)
class Rule:
    id: str
    severity: Severity
    category: Category
    title: str
    description: str


@dataclass(frozen=True)
class Finding:
    rule_id: str
    severity: Severity
    category: Category
    element_id: str | None
    path: str
    message: str
    suppressed: bool = False
    justification: str | None = None

    def as_dict(self) -> dict[str, object]:
        return {
            "rule_id": self.rule_id,
            "severity": self.severity,
            "category": self.category,
            "element_id": self.element_id,
            "path": self.path,
            "message": self.message,
            "suppressed": self.suppressed,
            "justification": self.justification,
        }


class _Ctx:
    def __init__(self, model: AppModel) -> None:
        self.model = model
        self.index = ModelIndex(model)
        self.refs = build_refs(model)
        self.referenced = {r.to_id for r in self.refs}
        # Every entity must have an access rule, so rules alone don't make an entity "used".
        self.used_outside_rules = {r.to_id for r in self.refs if r.kind != "access-entity"}
        self.access_by_entity: dict[str, list] = {}
        for rule in model.security.access:
            self.access_by_entity.setdefault(rule.entity, []).append(rule)

    def entities(self) -> Iterator[tuple[ModuleDef, EntityDef, str, str]]:
        for mi, mod in enumerate(self.model.modules):
            for ei, ent in enumerate(mod.entities):
                yield mod, ent, f"{mod.key}.{ent.name}", f"/modules/{mi}/entities/{ei}"

    def constraint_fields(self, rule, mod: ModuleDef, qualified: str) -> set[str]:
        if not rule.row_constraint:
            return set()
        try:
            return set(check(rule.row_constraint, CheckEnv(self.index.types_for(mod.key), qualified)).fields)
        except ExprError:
            return set()


RuleFn = Callable[[_Ctx], Iterator[tuple[str | None, str, str]]]  # (element_id, path, message)
_REGISTRY: list[tuple[Rule, RuleFn]] = []


def rule(id: str, severity: Severity, category: Category, title: str, description: str):
    def deco(fn: RuleFn) -> RuleFn:
        _REGISTRY.append((Rule(id, severity, category, title, description), fn))
        return fn

    return deco


def _indexed_fields(ent: EntityDef) -> set[str]:
    out = {f.name for f in ent.fields if f.primary_key or f.unique}
    out |= {idx.fields[0] for idx in ent.indexes}  # leading column is what a btree can seek on
    return out


# --- security ---------------------------------------------------------------------------


@rule("sec-constraint-not-compilable", "error", "security", "Row constraint cannot be compiled to SQL",
      "The runtime cannot translate this constraint to a query filter, so it would deny every request.")
def _(c: _Ctx):
    for i, r in enumerate(c.model.security.access):
        found = c.index.entities.get(r.entity)
        if not r.row_constraint or not found:
            continue
        try:
            res = check(r.row_constraint, CheckEnv(c.index.types_for(found[0].key), r.entity), BOOL)
            compile_predicate(res, SqlContext(current_user=UserRef("lint", set(c.model.security.roles))))
        except NotCompilable as e:
            yield r.element_id, f"/security/access/{i}/row_constraint", f"{e.message}"
        except ExprError:
            continue  # reported by validation


@rule("sec-constraint-on-nullable-field", "warning", "security", "Row constraint uses a nullable field",
      "Null-safe comparisons cannot use a plain index and a missing value can silently widen or narrow access.")
def _(c: _Ctx):
    for i, r in enumerate(c.model.security.access):
        found = c.index.entities.get(r.entity)
        if not found:
            continue
        mod, ent = found
        names = c.constraint_fields(r, mod, r.entity)
        nullable = sorted(
            f.name for f in ent.fields
            if f.name in names and not (f.required or f.primary_key or f.generated or f.computed)
        )
        if nullable:
            yield r.element_id, f"/security/access/{i}/row_constraint", f"constraint reads nullable field(s): {', '.join(nullable)}"


@rule("sec-unconstrained-write", "warning", "security", "Write access without a row constraint on user-owned data",
      "The entity has a reference to the user but a role can change any user's rows.")
def _(c: _Ctx):
    for mod, ent, q, _p in c.entities():
        owner_fields = [f for f in ent.fields if f.type == "ref:system.User"]
        if not owner_fields:
            continue
        for i, r in enumerate(c.model.security.access):
            if r.entity == q and WRITE_OPS & set(r.operations) and not r.row_constraint:
                yield r.element_id, f"/security/access/{i}", (
                    f"role '{r.role}' can {'/'.join(sorted(WRITE_OPS & set(r.operations)))} any {ent.name} "
                    f"although it is owned via '{owner_fields[0].name}'")


@rule("sec-write-without-read", "warning", "security", "Role can write but not read",
      "A role that modifies records it cannot read is usually a mistake.")
def _(c: _Ctx):
    for q, rules in c.access_by_entity.items():
        by_role: dict[str, set[str]] = {}
        for r in rules:
            by_role.setdefault(r.role, set()).update(r.operations)
        for i, r in enumerate(c.model.security.access):
            ops = by_role.get(r.role, set()) if r.entity == q else set()
            if ops & WRITE_OPS and "read" not in ops:
                yield r.element_id, f"/security/access/{i}", f"role '{r.role}' can write {q} but not read it"


@rule("sec-anonymous-access", "warning", "security", "Anonymous access enabled",
      "Anonymous access exposes pages without authentication and needs A3 approval.")
def _(c: _Ctx):
    if c.model.security.anonymous:
        yield None, "/security/anonymous", "anonymous access is enabled"


@rule("sec-superuser-role", "info", "security", "Role with unrestricted access to everything",
      "A role that can do every operation on every entity without constraints is effectively an administrator.")
def _(c: _Ctx):
    persistent = {q for _m, e, q, _p in c.entities() if not e.transient}
    for role in c.model.security.roles:
        full = {r.entity for r in c.model.security.access
                if r.role == role and set(r.operations) >= {"read", "create", "update", "delete"} and not r.row_constraint}
        if persistent and persistent <= full:
            yield None, "/security/roles", f"role '{role}' has unrestricted full access to every entity"


@rule("sec-sensitive-field-listed", "warning", "security", "Sensitive-looking field shown in a list page",
      "Field names such as password, secret or token should not be rendered in list views.")
def _(c: _Ctx):
    for mi, mod in enumerate(c.model.modules):
        for pi, pg in enumerate(mod.pages):
            if pg.type != "list":
                continue
            for col in pg.columns:
                if _SENSITIVE.search(col):
                    yield pg.element_id, f"/modules/{mi}/pages/{pi}/columns", f"column '{col}' looks sensitive"


# --- performance ------------------------------------------------------------------------


@rule("perf-unindexed-constraint-field", "warning", "performance", "Row-constraint field without an index",
      "Row constraints run on every query; the fields they filter on should be indexed (DESIGN.md 5.1).")
def _(c: _Ctx):
    for i, r in enumerate(c.model.security.access):
        found = c.index.entities.get(r.entity)
        if not found:
            continue
        mod, ent = found
        missing = sorted(c.constraint_fields(r, mod, r.entity) - _indexed_fields(ent))
        computed = {f.name for f in ent.fields if f.computed}
        missing = [m for m in missing if m not in computed]
        if missing:
            yield r.element_id, f"/security/access/{i}/row_constraint", f"no index leads with: {', '.join(missing)}"


@rule("perf-reference-without-index", "info", "performance", "Reference field without an index",
      "Joins and cascades on unindexed reference fields get slower as data grows.")
def _(c: _Ctx):
    for mod, ent, _q, path in c.entities():
        indexed = _indexed_fields(ent)
        for fi, f in enumerate(ent.fields):
            parsed = parse_field_type(f.type)
            if parsed and parsed[0] == "ref" and f.name not in indexed and f.type != "ref:system.User":
                yield f.element_id, f"{path}/fields/{fi}", f"reference '{f.name}' is not indexed"


@rule("perf-wide-entity", "info", "performance", "Entity with very many fields",
      "Entities with more than 40 fields are hard to maintain and slow to list.")
def _(c: _Ctx):
    for _m, ent, _q, path in c.entities():
        if len(ent.fields) > 40:
            yield ent.element_id, path, f"{ent.name} has {len(ent.fields)} fields"


@rule("perf-wide-list-page", "info", "performance", "List page with many columns",
      "More than 12 columns is rarely readable and loads more data than needed.")
def _(c: _Ctx):
    for mi, mod in enumerate(c.model.modules):
        for pi, pg in enumerate(mod.pages):
            if pg.type == "list" and len(pg.columns) > 12:
                yield pg.element_id, f"/modules/{mi}/pages/{pi}/columns", f"{len(pg.columns)} columns"


# --- maintainability --------------------------------------------------------------------


@rule("maint-unused-enumeration", "warning", "maintainability", "Enumeration is never used",
      "No field or expression refers to this enumeration.")
def _(c: _Ctx):
    for mi, mod in enumerate(c.model.modules):
        for xi, en in enumerate(mod.enumerations):
            if en.element_id not in c.referenced:
                yield en.element_id, f"/modules/{mi}/enumerations/{xi}", f"enumeration {en.name} is unused"


@rule("maint-unused-entity", "info", "maintainability", "Entity has no pages and is not referenced",
      "No page, reference field or expression uses the entity (access rules do not count).")
def _(c: _Ctx):
    for _m, ent, q, path in c.entities():
        if ent.element_id not in c.used_outside_rules and not ent.transient:
            yield ent.element_id, path, f"{q} is not used by any page, reference or expression"


@rule("maint-missing-display-name", "info", "maintainability", "Entity without a display name",
      "Display names make the generated UI and messages readable.")
def _(c: _Ctx):
    for _m, ent, _q, path in c.entities():
        if not ent.display_name:
            yield ent.element_id, path, f"{ent.name} has no display_name"


@rule("maint-single-value-enumeration", "warning", "maintainability", "Enumeration with one value",
      "A single-valued enumeration carries no information.")
def _(c: _Ctx):
    for mi, mod in enumerate(c.model.modules):
        for xi, en in enumerate(mod.enumerations):
            if len(en.values) == 1:
                yield en.element_id, f"/modules/{mi}/enumerations/{xi}", f"{en.name} has one value"


@rule("maint-duplicate-list-page", "info", "maintainability", "Several list pages for one entity",
      "Usually one list page per entity is enough.")
def _(c: _Ctx):
    for mi, mod in enumerate(c.model.modules):
        seen: dict[str, int] = {}
        for pi, pg in enumerate(mod.pages):
            if pg.type != "list":
                continue
            key = c.index.resolve_entity(mod.key, pg.entity) or pg.entity
            if key in seen:
                yield pg.element_id, f"/modules/{mi}/pages/{pi}", f"page '{pg.key}' duplicates a list of {key}"
            seen[key] = pi


@rule("maint-no-creation-timestamp", "info", "maintainability", "Entity has no creation timestamp",
      "A generated datetime field makes records auditable and sortable.")
def _(c: _Ctx):
    for _m, ent, _q, path in c.entities():
        if not ent.transient and not any(f.type == "datetime" and f.generated for f in ent.fields):
            yield ent.element_id, path, f"{ent.name} has no generated datetime field"


@rule("maint-long-expression", "info", "maintainability", "Very long expression",
      "Expressions over 300 characters are hard to review; consider computed fields.")
def _(c: _Ctx):
    for mod, ent, _q, path in c.entities():
        for fi, f in enumerate(ent.fields):
            for attr, src in (("computed/expr", f.computed.expr if f.computed else None), ("default_expr", f.default_expr)):
                if src and len(src) > 300:
                    yield f.element_id, f"{path}/fields/{fi}/{attr}", f"{len(src)} characters"
    for i, r in enumerate(c.model.security.access):
        if r.row_constraint and len(r.row_constraint) > 300:
            yield r.element_id, f"/security/access/{i}/row_constraint", f"{len(r.row_constraint)} characters"


@rule("maint-access-on-transient-entity", "warning", "maintainability", "Access rule on a transient entity",
      "Transient entities are never stored, so access rules on them have no effect.")
def _(c: _Ctx):
    transient = {q for _m, e, q, _p in c.entities() if e.transient}
    for i, r in enumerate(c.model.security.access):
        if r.entity in transient:
            yield r.element_id, f"/security/access/{i}", f"{r.entity} is transient"


# --- accessibility / i18n ---------------------------------------------------------------


@rule("a11y-column-without-label", "warning", "accessibility", "Displayed field without a display name",
      "Fields shown in pages need a human-readable label for screen readers and translation.")
def _(c: _Ctx):
    for mi, mod in enumerate(c.model.modules):
        for pi, pg in enumerate(mod.pages):
            q = c.index.resolve_entity(mod.key, pg.entity)
            for col in pg.columns:
                f = c.index.field(q, col) if q else None
                if f is not None and not f.display_name:
                    yield pg.element_id, f"/modules/{mi}/pages/{pi}/columns", f"field '{col}' has no display_name"


@rule("i18n-default-locale-not-listed", "warning", "accessibility", "Default locale missing from locales",
      "When locales are declared, the default locale must be one of them.")
def _(c: _Ctx):
    app = c.model.application
    if app.locales and app.default_locale not in app.locales:
        yield None, "/application/locales", f"default_locale {app.default_locale} is not in locales"


RULES: tuple[Rule, ...] = tuple(r for r, _ in _REGISTRY)


def lint(model: AppModel) -> list[Finding]:
    """Run every rule. ``model`` should be identified (see ``assign_element_ids``)."""
    ctx = _Ctx(model)
    valid_ids = {el.element_id for _, el in iter_elements(model)}
    suppress = {(s.rule, s.element_id): s.justification for s in model.lint_suppressions if s.element_id in valid_ids}
    out: list[Finding] = []
    for r, fn in _REGISTRY:
        for element_id, path, message in fn(ctx):
            why = suppress.get((r.id, element_id)) if element_id else None
            out.append(Finding(r.id, r.severity, r.category, element_id, path, message, why is not None, why))
    order = {"error": 0, "warning": 1, "info": 2}
    return sorted(out, key=lambda f: (f.suppressed, order[f.severity], f.rule_id, f.path))


def blocking(findings: list[Finding]) -> list[Finding]:
    return [f for f in findings if f.severity == "error" and not f.suppressed]


def catalog_markdown() -> str:
    lines = ["# Model Lint Rules", "",
             "Generated from `orchivio.model.lint` (`catalog_markdown()`); do not edit by hand.", "",
             "Error findings block a revision unless suppressed with `lint_suppressions` "
             "(`rule`, `element_id`, `justification` of at least 10 characters).", "",
             "| Rule | Severity | Category | What it flags |", "|---|---|---|---|"]
    for r in RULES:
        lines.append(f"| `{r.id}` | {r.severity} | {r.category} | **{r.title}.** {r.description} |")
    return "\n".join(lines) + "\n"

